public without sharing class ContactTriggerHandler {
    public static void beforeSave(List<Contact> contacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();

        for (Contact contactRecord : contacts) {
            if (contactRecord.AccountId != null) {
                accountIds.add(contactRecord.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT Id, BillingCountry, AccountSource
            FROM Account
            WHERE Id IN :accountIds
        ]);

        for (Contact contactRecord : contacts) {
            Account relatedAccount = accountsById.get(contactRecord.AccountId);
            if (relatedAccount == null) {
                continue;
            }

            if (String.isBlank(contactRecord.MailingCountry)) {
                contactRecord.MailingCountry = relatedAccount.BillingCountry;
            }

            if (isInsert && String.isBlank(contactRecord.LeadSource)) {
                contactRecord.LeadSource = relatedAccount.AccountSource;
            }
        }
    }

    public static void afterInsert(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();

        for (Contact contactRecord : contacts) {
            if (contactRecord.AccountId != null &&
                String.isNotBlank(contactRecord.Phone)) {
                accountIds.add(contactRecord.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT Id, Phone
            FROM Account
            WHERE Id IN :accountIds
        ]);

        List<Account> accountsToUpdate = new List<Account>();
        Set<Id> queuedAccountIds = new Set<Id>();

        for (Contact contactRecord : contacts) {
            Account relatedAccount = accountsById.get(contactRecord.AccountId);

            if (relatedAccount != null &&
                String.isNotBlank(contactRecord.Phone) &&
                String.isBlank(relatedAccount.Phone)) {
                relatedAccount.Phone = contactRecord.Phone;

                if (queuedAccountIds.add(relatedAccount.Id)) {
                    accountsToUpdate.add(relatedAccount);
                }
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
