public with sharing class ExchangeRateClient {
    public class ExchangeRateException extends Exception {
    }

    private static final String ENDPOINT =
        'callout:FB_Exchange_Rates/v1/latest';

    private class LatestRatesResponse {
        public Map<String, Decimal> rates;
    }

    public static Map<String, Decimal> getRates(
        String baseCurrency,
        Set<String> quoteCurrencies
    ) {
        String normalizedBase = normalizeCurrencyCode(baseCurrency, 'base currency');

        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException(
                'At least one quote currency is required.'
            );
        }

        Set<String> normalizedQuotes = new Set<String>();
        for (String quoteCurrency : quoteCurrencies) {
            normalizedQuotes.add(
                normalizeCurrencyCode(quoteCurrency, 'quote currency')
            );
        }

        List<String> sortedQuotes = new List<String>(normalizedQuotes);
        sortedQuotes.sort();

        String endpoint = ENDPOINT
            + '?base=' + EncodingUtil.urlEncode(normalizedBase, 'UTF-8')
            + '&symbols=' + String.join(sortedQuotes, ',');

        HttpResponse response;
        try {
            Http http = new Http();
            response = http.send(createRequest(endpoint));

            if (response.getStatusCode() == 503) {
                response = http.send(createRequest(endpoint));
            }
        } catch (CalloutException e) {
            throw new ExchangeRateException(
                'Exchange rate service callout failed: ' + e.getMessage()
            );
        }

        Integer statusCode = response.getStatusCode();
        if (statusCode != 200) {
            throw new ExchangeRateException(
                'Exchange rate service returned HTTP status ' + statusCode + '.'
            );
        }

        LatestRatesResponse payload;
        try {
            payload = (LatestRatesResponse) JSON.deserialize(
                response.getBody(),
                LatestRatesResponse.class
            );
        } catch (Exception e) {
            throw new ExchangeRateException(
                'Exchange rate response body could not be parsed.'
            );
        }

        if (payload == null || payload.rates == null) {
            throw new ExchangeRateException(
                'Exchange rate response body could not be parsed.'
            );
        }

        Map<String, Decimal> requestedRates = new Map<String, Decimal>();
        for (String quoteCurrency : normalizedQuotes) {
            Decimal rate = payload.rates.get(quoteCurrency);
            if (rate == null) {
                throw new ExchangeRateException(
                    'No exchange rate was returned for ' + quoteCurrency + '.'
                );
            }
            requestedRates.put(quoteCurrency, rate);
        }

        return requestedRates;
    }

    private static HttpRequest createRequest(String endpoint) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint(endpoint);
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');
        return request;
    }

    private static String normalizeCurrencyCode(
        String currencyCode,
        String description
    ) {
        if (currencyCode == null) {
            throw new ExchangeRateException(
                'Invalid ' + description + '.'
            );
        }

        String normalizedCode = currencyCode.trim().toUpperCase();
        if (!Pattern.matches('^[A-Z]{3}$', normalizedCode)) {
            throw new ExchangeRateException(
                'Invalid ' + description + ': ' + currencyCode + '.'
            );
        }

        return normalizedCode;
    }
}
