public with sharing class RecordSearchService {
    public class SearchException extends Exception {
    }

    @AuraEnabled(cacheable=true)
    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            if (maxRows == null || maxRows < 1 || maxRows > 200) {
                throw new SearchException('maxRows must be between 1 and 200.');
            }

            if (fields == null || fields.isEmpty()) {
                throw new SearchException('At least one field must be requested.');
            }

            Schema.SObjectType objectType = findObjectType(objectApiName);
            if (objectType == null) {
                throw new SearchException('The requested object does not exist.');
            }

            Schema.DescribeSObjectResult objectDescribe = objectType.getDescribe();

            if (!objectDescribe.isAccessible()) {
                throw new SearchException('The running user cannot read the requested object.');
            }

            if (!objectDescribe.isQueryable()) {
                throw new SearchException('The requested object cannot be queried.');
            }

            Map<String, Schema.SObjectField> fieldsByLowerName =
                buildCaseInsensitiveFieldMap(objectDescribe.fields.getMap());

            Schema.SObjectField idField = fieldsByLowerName.get('id');
            if (idField == null || !idField.getDescribe().isAccessible()) {
                throw new SearchException('The running user cannot read the Id field.');
            }

            List<String> selectFields = new List<String>{ 'Id' };
            Set<String> selectedFieldNames = new Set<String>{ 'id' };

            for (String requestedFieldName : fields) {
                Schema.SObjectField fieldToken =
                    requireField(fieldsByLowerName, requestedFieldName);
                Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();

                if (!fieldDescribe.isAccessible()) {
                    throw new SearchException(
                        'The running user cannot read field ' + fieldDescribe.getName() + '.'
                    );
                }

                String canonicalName = fieldDescribe.getName();
                String normalizedName = canonicalName.toLowerCase();

                if (!selectedFieldNames.contains(normalizedName)) {
                    selectFields.add(canonicalName);
                    selectedFieldNames.add(normalizedName);
                }
            }

            List<String> conditions = new List<String>();
            Map<String, Object> bindValues = new Map<String, Object>();

            if (filters != null && !filters.isEmpty()) {
                Integer bindIndex = 0;

                for (String filterFieldName : filters.keySet()) {
                    Schema.SObjectField fieldToken =
                        requireField(fieldsByLowerName, filterFieldName);
                    Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();

                    if (!fieldDescribe.isAccessible()) {
                        throw new SearchException(
                            'The running user cannot read field ' + fieldDescribe.getName() + '.'
                        );
                    }

                    if (!fieldDescribe.isFilterable()) {
                        throw new SearchException(
                            'Field ' + fieldDescribe.getName() + ' cannot be filtered.'
                        );
                    }

                    String bindName = 'filterValue' + String.valueOf(bindIndex);
                    conditions.add(fieldDescribe.getName() + ' = :' + bindName);
                    bindValues.put(bindName, filters.get(filterFieldName));
                    bindIndex++;
                }
            }

            String canonicalOrderByField;
            if (String.isNotBlank(orderByField)) {
                Schema.SObjectField fieldToken =
                    requireField(fieldsByLowerName, orderByField);
                Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();

                if (!fieldDescribe.isAccessible()) {
                    throw new SearchException(
                        'The running user cannot read field ' + fieldDescribe.getName() + '.'
                    );
                }

                if (!fieldDescribe.isSortable()) {
                    throw new SearchException(
                        'Field ' + fieldDescribe.getName() + ' cannot be sorted.'
                    );
                }

                canonicalOrderByField = fieldDescribe.getName();
            }

            String soql =
                'SELECT ' + String.join(selectFields, ', ') +
                ' FROM ' + objectDescribe.getName();

            if (!conditions.isEmpty()) {
                soql += ' WHERE ' + String.join(conditions, ' AND ');
            }

            if (canonicalOrderByField != null) {
                soql += ' ORDER BY ' + canonicalOrderByField + ' ASC';
            }

            soql += ' LIMIT ' + String.valueOf(maxRows);

            return Database.queryWithBinds(
                soql,
                bindValues,
                AccessLevel.USER_MODE
            );
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            throw new SearchException('The search could not be completed: ' + e.getMessage());
        }
    }

    private static Schema.SObjectType findObjectType(String objectApiName) {
        if (String.isBlank(objectApiName)) {
            return null;
        }

        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();

        for (String availableObjectName : globalDescribe.keySet()) {
            if (availableObjectName.equalsIgnoreCase(objectApiName)) {
                return globalDescribe.get(availableObjectName);
            }
        }

        return null;
    }

    private static Map<String, Schema.SObjectField> buildCaseInsensitiveFieldMap(
        Map<String, Schema.SObjectField> fieldMap
    ) {
        Map<String, Schema.SObjectField> result =
            new Map<String, Schema.SObjectField>();

        for (String fieldName : fieldMap.keySet()) {
            result.put(fieldName.toLowerCase(), fieldMap.get(fieldName));
        }

        return result;
    }

    private static Schema.SObjectField requireField(
        Map<String, Schema.SObjectField> fieldsByLowerName,
        String fieldName
    ) {
        if (String.isBlank(fieldName)) {
            throw new SearchException('A requested field does not exist.');
        }

        Schema.SObjectField fieldToken =
            fieldsByLowerName.get(fieldName.toLowerCase());

        if (fieldToken == null) {
            throw new SearchException('Field ' + fieldName + ' does not exist.');
        }

        return fieldToken;
    }
}
