public with sharing class OrderPayloadParser {
    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class PayloadException extends Exception {
    }

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Request body must not be blank.');
        }

        try {
            Object parsed = JSON.deserializeUntyped(body);

            if (!(parsed instanceof Map<String, Object>)) {
                throw new PayloadException('Payload must be a JSON object.');
            }

            Map<String, Object> root = (Map<String, Object>) parsed;
            Order order = new Order();

            order.orderNumber = asString(root.get('number'), 'number');
            if (String.isBlank(order.orderNumber)) {
                throw new PayloadException('Order number is required.');
            }

            Object dateValue = root.get('date');
            if (dateValue != null) {
                String dateText = asString(dateValue, 'date');
                if (!dateText.matches('\\d{4}-\\d{2}-\\d{2}')) {
                    throw new PayloadException('Order date must use yyyy-MM-dd format.');
                }
                order.orderDate = Date.valueOf(dateText);
            }

            Object currencyValue = root.get('currency');
            if (currencyValue != null) {
                order.currencyCode = asString(currencyValue, 'currency');
            }

            Object customerValue = root.get('customer');
            if (customerValue != null) {
                if (!(customerValue instanceof Map<String, Object>)) {
                    throw new PayloadException('customer must be a JSON object.');
                }

                Map<String, Object> customer =
                    (Map<String, Object>) customerValue;
                Object emailValue = customer.get('email');

                if (emailValue != null) {
                    order.customerEmail = asString(
                        emailValue,
                        'customer.email'
                    );
                }
            }

            order.lines = new List<Line>();
            order.total = 0;

            Object linesValue = root.get('lines');
            if (linesValue == null) {
                return order;
            }

            if (!(linesValue instanceof List<Object>)) {
                throw new PayloadException('lines must be a JSON array.');
            }

            for (Object lineValue : (List<Object>) linesValue) {
                if (!(lineValue instanceof Map<String, Object>)) {
                    throw new PayloadException(
                        'Each line must be a JSON object.'
                    );
                }

                Map<String, Object> lineData =
                    (Map<String, Object>) lineValue;
                Line line = parseLine(lineData);

                order.lines.add(line);
                order.total += line.lineTotal;
            }

            return order;
        } catch (PayloadException ex) {
            throw ex;
        } catch (Exception ex) {
            throw new PayloadException(
                'Invalid order payload: ' + ex.getMessage()
            );
        }
    }

    public static String toAcknowledgement(Order order) {
        JSONGenerator generator = JSON.createGenerator(false);
        generator.writeStartObject();
        generator.writeStringField('number', order.orderNumber);
        generator.writeStringField('status', 'RECEIVED');
        generator.writeNumberField(
            'lineCount',
            order.lines == null ? 0 : order.lines.size()
        );
        generator.writeNumberField(
            'total',
            order.total == null ? 0 : order.total
        );
        generator.writeEndObject();
        return generator.getAsString();
    }

    private static Line parseLine(Map<String, Object> lineData) {
        Line line = new Line();

        line.sku = asString(lineData.get('sku'), 'lines.sku');
        if (String.isBlank(line.sku)) {
            throw new PayloadException('Each line must have a sku.');
        }

        Decimal quantityValue = asDecimal(
            lineData.get('quantity'),
            'lines.quantity'
        );
        Decimal roundedQuantity = quantityValue.setScale(0);

        if (quantityValue != roundedQuantity || quantityValue <= 0) {
            throw new PayloadException(
                'Line quantity must be a positive integer.'
            );
        }

        try {
            line.quantity = Integer.valueOf(String.valueOf(roundedQuantity));
        } catch (Exception ex) {
            throw new PayloadException(
                'Line quantity must be a positive integer.'
            );
        }

        line.unitPrice = asDecimal(
            lineData.get('unitPrice'),
            'lines.unitPrice'
        );
        if (line.unitPrice < 0) {
            throw new PayloadException(
                'Line unitPrice must not be negative.'
            );
        }

        Object discountValue = lineData.get('discount');
        line.discount = discountValue == null
            ? 0
            : asDecimal(discountValue, 'lines.discount');

        if (line.discount < 0 || line.discount > 1) {
            throw new PayloadException(
                'Line discount must be between 0 and 1.'
            );
        }

        line.lineTotal = (
            line.quantity *
            line.unitPrice *
            (1 - line.discount)
        ).setScale(2, RoundingMode.HALF_UP);

        return line;
    }

    private static String asString(Object value, String fieldName) {
        if (value == null) {
            return null;
        }

        if (!(value instanceof String)) {
            throw new PayloadException(fieldName + ' must be a string.');
        }

        return (String) value;
    }

    private static Decimal asDecimal(Object value, String fieldName) {
        if (value == null) {
            throw new PayloadException(fieldName + ' is required.');
        }

        if (
            !(value instanceof Integer) &&
            !(value instanceof Long) &&
            !(value instanceof Decimal) &&
            !(value instanceof Double)
        ) {
            throw new PayloadException(fieldName + ' must be a number.');
        }

        try {
            return Decimal.valueOf(String.valueOf(value));
        } catch (Exception ex) {
            throw new PayloadException(fieldName + ' must be a number.');
        }
    }
}
