public class PicklistService {
    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {
    }

    public static List<Option> activeOptions(
        String objectApiName,
        String fieldApiName
    ) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name must not be blank.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name must not be blank.');
        }

        String requestedObjectName = objectApiName.trim();
        String requestedFieldName = fieldApiName.trim();

        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectType objectType;

        for (String describedObjectName : globalDescribe.keySet()) {
            if (describedObjectName.equalsIgnoreCase(requestedObjectName)) {
                objectType = globalDescribe.get(describedObjectName);
                break;
            }
        }

        if (objectType == null) {
            throw new PicklistServiceException(
                'Object does not exist: ' + requestedObjectName
            );
        }

        Map<String, Schema.SObjectField> fieldMap =
            objectType.getDescribe().fields.getMap();
        Schema.SObjectField objectField;

        for (String describedFieldName : fieldMap.keySet()) {
            if (describedFieldName.equalsIgnoreCase(requestedFieldName)) {
                objectField = fieldMap.get(describedFieldName);
                break;
            }
        }

        if (objectField == null) {
            throw new PicklistServiceException(
                'Field does not exist on object ' +
                requestedObjectName +
                ': ' +
                requestedFieldName
            );
        }

        Schema.DescribeFieldResult fieldDescribe = objectField.getDescribe();
        Schema.DisplayType fieldType = fieldDescribe.getType();

        if (
            fieldType != Schema.DisplayType.Picklist &&
            fieldType != Schema.DisplayType.MultiPicklist
        ) {
            throw new PicklistServiceException(
                'Field is not a picklist or multi-select picklist: ' +
                requestedObjectName +
                '.' +
                requestedFieldName
            );
        }

        List<Option> options = new List<Option>();

        for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
            if (entry.isActive()) {
                options.add(
                    new Option(
                        entry.getValue(),
                        entry.getLabel(),
                        entry.isDefaultValue()
                    )
                );
            }
        }

        return options;
    }
}
