public with sharing class AccountScoringJob implements Queueable {
    private static final Integer CHUNK_SIZE = 200;
    private static final Integer MAXIMUM_CHAIN_DEPTH = 250;

    private final List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = new List<Id>();

        if (accountIds != null) {
            this.accountIds.addAll(accountIds);
        }
    }

    public void execute(QueueableContext context) {
        Integer currentChunkSize = Math.min(CHUNK_SIZE, accountIds.size());
        List<Id> currentAccountIds = new List<Id>();

        for (Integer index = 0; index < currentChunkSize; index++) {
            currentAccountIds.add(accountIds[index]);
        }

        List<Account> accountsToUpdate = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :currentAccountIds
        ];

        for (Account accountRecord : accountsToUpdate) {
            if (accountRecord.AnnualRevenue >= 1000000) {
                accountRecord.Rating = 'Hot';
            } else if (accountRecord.AnnualRevenue >= 100000) {
                accountRecord.Rating = 'Warm';
            } else {
                accountRecord.Rating = 'Cold';
            }
        }

        update accountsToUpdate;

        if (accountIds.size() > currentChunkSize) {
            List<Id> remainingAccountIds = new List<Id>();

            for (
                Integer index = currentChunkSize;
                index < accountIds.size();
                index++
            ) {
                remainingAccountIds.add(accountIds[index]);
            }

            System.enqueueJob(new AccountScoringJob(remainingAccountIds));
        }
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }

        AsyncOptions options = new AsyncOptions();
        options.MaximumQueueableStackDepth = MAXIMUM_CHAIN_DEPTH;

        return System.enqueueJob(
            new AccountScoringJob(accountIds),
            options
        );
    }
}
