public without sharing class OpportunityPipelineHandler {
    public static void handle(
        System.TriggerOperation operation,
        List<Opportunity> newRecords,
        Map<Id, Opportunity> oldMap
    ) {
        Set<Id> affectedAccountIds = new Set<Id>();

        if (
            operation == System.TriggerOperation.AFTER_INSERT ||
            operation == System.TriggerOperation.AFTER_UNDELETE
        ) {
            for (Opportunity opportunityRecord : newRecords) {
                if (!opportunityRecord.IsClosed) {
                    addAccountId(
                        affectedAccountIds,
                        opportunityRecord.AccountId
                    );
                }
            }
        } else if (operation == System.TriggerOperation.AFTER_DELETE) {
            for (Opportunity opportunityRecord : oldMap.values()) {
                if (!opportunityRecord.IsClosed) {
                    addAccountId(
                        affectedAccountIds,
                        opportunityRecord.AccountId
                    );
                }
            }
        } else if (operation == System.TriggerOperation.AFTER_UPDATE) {
            for (Opportunity opportunityRecord : newRecords) {
                Opportunity oldOpportunity = oldMap.get(opportunityRecord.Id);

                Boolean contributionChanged =
                    oldOpportunity.AccountId != opportunityRecord.AccountId ||
                    oldOpportunity.Amount != opportunityRecord.Amount ||
                    oldOpportunity.IsClosed != opportunityRecord.IsClosed;

                if (!contributionChanged) {
                    continue;
                }

                if (!oldOpportunity.IsClosed) {
                    addAccountId(
                        affectedAccountIds,
                        oldOpportunity.AccountId
                    );
                }

                if (!opportunityRecord.IsClosed) {
                    addAccountId(
                        affectedAccountIds,
                        opportunityRecord.AccountId
                    );
                }
            }
        }

        if (affectedAccountIds.isEmpty()) {
            return;
        }

        /*
         * Lock the parent Accounts before calculating the aggregates. This
         * serializes concurrent roll-up calculations for the same Accounts
         * and prevents a transaction from overwriting newer totals with a
         * result calculated before it obtained the Account lock.
         */
        List<Account> lockedAccounts = [
            SELECT
                Id,
                FB_Open_Pipeline__c,
                FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :affectedAccountIds
            ORDER BY Id
            FOR UPDATE
        ];

        if (lockedAccounts.isEmpty()) {
            return;
        }

        Set<Id> existingAccountIds = new Map<Id, Account>(
            lockedAccounts
        ).keySet();

        Map<Id, Decimal> pipelineByAccountId = new Map<Id, Decimal>();
        Map<Id, Integer> countByAccountId = new Map<Id, Integer>();

        for (AggregateResult result : [
            SELECT
                AccountId,
                SUM(Amount) openPipeline,
                COUNT(Id) openOpportunityCount
            FROM Opportunity
            WHERE AccountId IN :existingAccountIds
                AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) result.get('AccountId');
            Decimal openPipeline = (Decimal) result.get('openPipeline');

            pipelineByAccountId.put(
                accountId,
                openPipeline == null ? 0 : openPipeline
            );
            countByAccountId.put(
                accountId,
                (Integer) result.get('openOpportunityCount')
            );
        }

        List<Account> accountsToUpdate = new List<Account>();

        for (Account lockedAccount : lockedAccounts) {
            Decimal desiredPipeline = pipelineByAccountId.containsKey(
                lockedAccount.Id
            )
                ? pipelineByAccountId.get(lockedAccount.Id)
                : 0;

            Integer desiredCount = countByAccountId.containsKey(
                lockedAccount.Id
            )
                ? countByAccountId.get(lockedAccount.Id)
                : 0;

            if (
                lockedAccount.FB_Open_Pipeline__c != desiredPipeline ||
                lockedAccount.FB_Open_Opportunities__c != desiredCount
            ) {
                accountsToUpdate.add(new Account(
                    Id = lockedAccount.Id,
                    FB_Open_Pipeline__c = desiredPipeline,
                    FB_Open_Opportunities__c = desiredCount
                ));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }

    private static void addAccountId(
        Set<Id> accountIds,
        Id accountId
    ) {
        if (accountId != null) {
            accountIds.add(accountId);
        }
    }
}
