public inherited sharing class Opportunities extends fflib_SObjectDomain {
    public Opportunities(List<Opportunity> records) {
        super(records);
    }

    public override void onAfterInsert() {
        Set<Id> qualifyingOpportunityIds = new Set<Id>();

        for (Opportunity opportunity : (List<Opportunity>) Records) {
            if (opportunity.StageName == 'Closed Won') {
                qualifyingOpportunityIds.add(opportunity.Id);
            }
        }

        startFulfilment(qualifyingOpportunityIds);
    }

    public override void onAfterUpdate(Map<Id, SObject> existingRecords) {
        Set<Id> qualifyingOpportunityIds = new Set<Id>();

        for (Opportunity opportunity : (List<Opportunity>) Records) {
            Opportunity existingOpportunity =
                (Opportunity) existingRecords.get(opportunity.Id);

            if (
                opportunity.StageName == 'Closed Won' &&
                existingOpportunity.StageName != 'Closed Won'
            ) {
                qualifyingOpportunityIds.add(opportunity.Id);
            }
        }

        startFulfilment(qualifyingOpportunityIds);
    }

    private static void startFulfilment(Set<Id> opportunityIds) {
        if (opportunityIds.isEmpty()) {
            return;
        }

        IOpportunityFulfilmentService fulfilmentService =
            (IOpportunityFulfilmentService) Application.Service.newInstance(
                IOpportunityFulfilmentService.class
            );

        fulfilmentService.startFulfilment(opportunityIds);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities((List<Opportunity>) records);
        }
    }
}
