public with sharing class PipelineSummary {
    /**
     * Returns opportunity amount totals for the four managed open stages.
     *
     * A single grouped aggregate query is used instead of four queries. This is
     * equally readable, consumes fewer governor-limit queries, and remains
     * independent of the number of matching opportunities.
     */
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        if (fromDate == null || toDate == null) {
            throw new IllegalArgumentException(
                'fromDate and toDate must both be provided.'
            );
        }
        if (fromDate > toDate) {
            throw new IllegalArgumentException(
                'fromDate must be on or before toDate.'
            );
        }

        List<String> managedStages = new List<String>{
            'Prospecting',
            'Qualification',
            'Proposal/Price Quote',
            'Negotiation/Review'
        };

        Map<String, Decimal> totals = new Map<String, Decimal>();
        for (String stageName : managedStages) {
            totals.put(stageName, 0);
        }

        for (AggregateResult result : [
            SELECT StageName, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE StageName IN :managedStages
                AND CloseDate >= :fromDate
                AND CloseDate <= :toDate
            WITH USER_MODE
            GROUP BY StageName
        ]) {
            String stageName = (String) result.get('StageName');
            Decimal totalAmount = (Decimal) result.get('totalAmount');
            totals.put(stageName, totalAmount == null ? 0 : totalAmount);
        }

        return totals;
    }
}
