/**
 * Closes open opportunities whose CloseDate is before a specified cutoff.
 *
 * This synchronous implementation is appropriate for a few thousand records.
 * If the possible volume could exceed the synchronous limit of 10,000 DML rows,
 * this process should instead use Batch Apex. A SOQL for loop reduces heap usage
 * but does not create separate transactions or bypass governor limits.
 */
public without sharing class StaleOpportunityCloser {
    public static Integer closeStale(Date cutoff) {
        if (cutoff == null) {
            throw new IllegalArgumentException('cutoff must not be null');
        }

        Integer closedCount = 0;

        for (List<Opportunity> chunk : [
            SELECT Id
            FROM Opportunity
            WHERE IsClosed = false
              AND CloseDate < :cutoff
        ]) {
            for (Opportunity opportunity : chunk) {
                opportunity.StageName = 'Closed Lost';
            }

            update chunk;
            closedCount += chunk.size();
        }

        return closedCount;
    }
}
