public with sharing class ErpCustomerSync implements Queueable, Database.AllowsCallouts {
    private static final String ENDPOINT = 'callout:ERP/api/customers';

    private final List<CustomerPayload> customers;

    private ErpCustomerSync(List<CustomerPayload> customers) {
        this.customers = customers;
    }

    public static void enqueue(List<Account> accounts) {
        if (accounts == null || accounts.isEmpty()) {
            return;
        }

        List<CustomerPayload> payload = new List<CustomerPayload>();

        for (Account account : accounts) {
            payload.add(new CustomerPayload(
                String.valueOf(account.Id),
                account.Name,
                account.BillingCountry
            ));
        }

        System.enqueueJob(new ErpCustomerSync(payload));
    }

    public void execute(QueueableContext context) {
        if (customers == null || customers.isEmpty()) {
            return;
        }

        HttpRequest request = new HttpRequest();
        request.setEndpoint(ENDPOINT);
        request.setMethod('POST');
        request.setHeader('Content-Type', 'application/json');
        request.setBody(JSON.serialize(customers, false));

        Http http = new Http();
        http.send(request);
    }

    private class CustomerPayload {
        public String salesforceId;
        public String name;
        public String country;

        private CustomerPayload(
            String salesforceId,
            String name,
            String country
        ) {
            this.salesforceId = salesforceId;
            this.name = name;
            this.country = country;
        }
    }
}
