trigger OpportunityTrigger on Opportunity (after insert, after update) {
    Set<Id> accountIds = new Set<Id>();

    for (Opportunity opp : Trigger.new) {
        Opportunity oldOpp = Trigger.isUpdate ? Trigger.oldMap.get(opp.Id) : null;

        Boolean requiresRecalculation =
            Trigger.isInsert ||
            opp.StageName != oldOpp.StageName ||
            opp.Amount != oldOpp.Amount ||
            opp.AccountId != oldOpp.AccountId;

        if (!requiresRecalculation) {
            continue;
        }

        if (opp.AccountId != null) {
            accountIds.add(opp.AccountId);
        }

        // Recalculate the previous account as well when an opportunity moves.
        if (
            Trigger.isUpdate &&
            opp.AccountId != oldOpp.AccountId &&
            oldOpp.AccountId != null
        ) {
            accountIds.add(oldOpp.AccountId);
        }
    }

    /*
     * A batch of 200 opportunities cannot make one future call per record
     * because a transaction is limited to 50 future invocations. Submit one
     * bulk future call instead.
     */
    if (!accountIds.isEmpty()) {
        AccountRatingService.recalculate(accountIds);
    }
}
