public without sharing class AccountRatingService {
    private static final Decimal HOT_PIPELINE_THRESHOLD = 100000;

    /*
     * This service deliberately runs without sharing so the derived rating is
     * based on the account's complete pipeline, not only opportunities visible
     * to the user whose transaction invoked the automation.
     */
    @future
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Map<Id, Decimal> maximumOpenAmountByAccount = new Map<Id, Decimal>();

        for (AggregateResult result : [
            SELECT AccountId accountId, MAX(Amount) maximumAmount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            maximumOpenAmountByAccount.put(
                (Id) result.get('accountId'),
                (Decimal) result.get('maximumAmount')
            );
        }

        List<Account> accountsToUpdate = new List<Account>();

        for (Account accountRecord : [
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            String calculatedRating;

            if (!maximumOpenAmountByAccount.containsKey(accountRecord.Id)) {
                calculatedRating = 'Cold';
            } else {
                Decimal maximumAmount =
                    maximumOpenAmountByAccount.get(accountRecord.Id);

                calculatedRating =
                    maximumAmount != null &&
                    maximumAmount >= HOT_PIPELINE_THRESHOLD
                        ? 'Hot'
                        : 'Warm';
            }

            if (accountRecord.Rating != calculatedRating) {
                accountRecord.Rating = calculatedRating;
                accountsToUpdate.add(accountRecord);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
