public inherited sharing class LineItemDiscountHandler {
    /**
     * Applies the standard product-family discount to new lines whose Discount
     * was not explicitly provided.
     *
     * PricingRules.standardDiscountFor(Id) cannot be called once per line
     * because it performs a Product2 query on every invocation, exceeding the
     * SOQL limit for CPQ transactions containing up to 200 lines. Product
     * families are therefore queried once, while the pricing decision remains
     * owned by PricingRules through standardDiscountForFamily(String).
     */
    public static void applyStandardDiscounts(
        List<OpportunityLineItem> newLines
    ) {
        Set<Id> productIds = new Set<Id>();

        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                productIds.add(line.Product2Id);
            }
        }

        if (productIds.isEmpty()) {
            return;
        }

        Map<Id, Product2> productsById = new Map<Id, Product2>([
            SELECT Family
            FROM Product2
            WHERE Id IN :productIds
        ]);

        for (OpportunityLineItem line : newLines) {
            if (line.Discount != null || line.Product2Id == null) {
                continue;
            }

            Product2 product = productsById.get(line.Product2Id);
            if (product != null) {
                line.Discount =
                    PricingRules.standardDiscountForFamily(product.Family);
            }
        }
    }
}
