public with sharing class LeadContactMatcher {
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        List<Id> matches = new List<Id>();

        if (leads == null) {
            return matches;
        }

        Map<String, Id> firstContactIdByEmail = new Map<String, Id>();

        if (contacts != null) {
            for (Contact contactRecord : contacts) {
                if (contactRecord == null) {
                    continue;
                }

                String normalizedEmail = normalizeEmail(contactRecord.Email);
                if (normalizedEmail != null &&
                    !firstContactIdByEmail.containsKey(normalizedEmail)) {
                    firstContactIdByEmail.put(normalizedEmail, contactRecord.Id);
                }
            }
        }

        for (Lead leadRecord : leads) {
            String normalizedEmail =
                leadRecord == null ? null : normalizeEmail(leadRecord.Email);

            matches.add(
                normalizedEmail == null
                    ? null
                    : firstContactIdByEmail.get(normalizedEmail)
            );
        }

        return matches;
    }

    private static String normalizeEmail(String email) {
        return String.isBlank(email) ? null : email.trim().toLowerCase();
    }
}
