public class CaseSurveyJob implements Queueable, Database.AllowsCallouts {
    private Id caseId;
    private List<Id> remainingCaseIds;

    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
        this.remainingCaseIds = new List<Id>();
    }

    public CaseSurveyJob(List<Id> caseIds) {
        this.remainingCaseIds = new List<Id>();

        if (caseIds != null && !caseIds.isEmpty()) {
            this.caseId = caseIds[0];

            for (Integer index = 1; index < caseIds.size(); index++) {
                this.remainingCaseIds.add(caseIds[index]);
            }
        }
    }

    public void execute(QueueableContext context) {
        try {
            if (caseId == null) {
                return;
            }

            List<Case> cases = [
                SELECT Id, CaseNumber, ContactId
                FROM Case
                WHERE Id = :caseId
                LIMIT 1
            ];

            if (!cases.isEmpty() && cases[0].ContactId != null) {
                Case caseRecord = cases[0];

                Task surveyTask = new Task(
                    WhatId = caseRecord.Id,
                    WhoId = caseRecord.ContactId,
                    Subject = 'CSAT survey: ' + caseRecord.CaseNumber,
                    ActivityDate = Date.today().addDays(2),
                    Status = 'Not Started'
                );

                Database.SaveResult result = Database.insert(surveyTask, false);

                if (!result.isSuccess()) {
                    for (Database.Error error : result.getErrors()) {
                        System.debug(
                            LoggingLevel.ERROR,
                            'Unable to create a CSAT survey task for Case ' +
                            caseId + ': ' + error.getMessage()
                        );
                    }
                }
            }
        } catch (Exception error) {
            /*
             * Do not prevent subsequent Cases from being processed if this
             * Case encounters an unexpected error.
             */
            System.debug(
                LoggingLevel.ERROR,
                'Unable to process the CSAT survey for Case ' +
                caseId + ': ' + error.getMessage() + '\n' +
                error.getStackTraceString()
            );
        } finally {
            /*
             * An asynchronous transaction may enqueue only one additional
             * Queueable job. Chaining creates one execution per Case while
             * supporting trigger batches larger than the synchronous limit
             * of 50 enqueued jobs.
             */
            if (!remainingCaseIds.isEmpty()) {
                System.enqueueJob(new CaseSurveyJob(remainingCaseIds));
            }
        }
    }
}
