/**
 * Sends renewal reminders to opportunity owners.
 *
 * Messaging.sendEmail must not be called once per opportunity. Apex permits
 * only 10 sendEmail invocations per transaction, so that approach would fail
 * when processing more than 10 opportunities. A single bulk call with
 * allOrNone set to false preserves per-message failure isolation while
 * supporting the job's bulk input.
 */
public with sharing class RenewalReminderService {
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        Set<Id> uniqueOpportunityIds = new Set<Id>();
        for (Id opportunityId : opportunityIds) {
            if (opportunityId != null) {
                uniqueOpportunityIds.add(opportunityId);
            }
        }

        if (uniqueOpportunityIds.isEmpty()) {
            return 0;
        }

        List<Messaging.SingleEmailMessage> messages =
            new List<Messaging.SingleEmailMessage>();

        for (Opportunity opportunity : [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :uniqueOpportunityIds
            WITH USER_MODE
        ]) {
            Messaging.SingleEmailMessage message =
                new Messaging.SingleEmailMessage();

            message.setTargetObjectId(opportunity.OwnerId);
            message.setSaveAsActivity(false);
            message.setSubject('Renewal due: ' + opportunity.Name);
            message.setPlainTextBody(
                'The renewal opportunity "' + opportunity.Name +
                '" has a close date of ' + String.valueOf(opportunity.CloseDate) + '.'
            );

            messages.add(message);
        }

        if (messages.isEmpty()) {
            return 0;
        }

        Messaging.SendEmailResult[] results =
            Messaging.sendEmail(messages, false);

        Integer successfulEmailCount = 0;
        for (Messaging.SendEmailResult result : results) {
            if (result.isSuccess()) {
                successfulEmailCount++;
            }
        }

        return successfulEmailCount;
    }
}
