```apex
public without sharing class AccountCountrySync {
    public static void syncContacts(
        List<Account> updatedAccounts,
        Map<Id, Account> oldAccountsById
    ) {
        Map<Id, String> previousCountryByAccountId = new Map<Id, String>();
        Map<Id, String> newCountryByAccountId = new Map<Id, String>();
        Set<String> previousCountries = new Set<String>();

        for (Account account : updatedAccounts) {
            String previousCountry = oldAccountsById.get(account.Id).BillingCountry;

            if (account.BillingCountry != previousCountry) {
                previousCountryByAccountId.put(account.Id, previousCountry);
                newCountryByAccountId.put(account.Id, account.BillingCountry);

                if (!String.isBlank(previousCountry)) {
                    previousCountries.add(previousCountry);
                }
            }
        }

        if (previousCountryByAccountId.isEmpty()) {
            return;
        }

        /*
         * Querying every Contact in the org would exceed Salesforce's 50,000-row
         * synchronous query limit and the Apex heap limit in an org with roughly
         * 2.3 million Contacts. Instead, this single query is restricted to Contacts
         * belonging to changed Accounts and to potentially eligible countries.
         */
        Map<Id, Contact> contactsById = new Map<Id, Contact>([
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :previousCountryByAccountId.keySet()
            AND (
                MailingCountry = NULL
                OR MailingCountry IN :previousCountries
            )
        ]);

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact contact : contactsById.values()) {
            String previousCountry =
                previousCountryByAccountId.get(contact.AccountId);

            if (
                String.isBlank(contact.MailingCountry)
                || contact.MailingCountry == previousCountry
            ) {
                contact.MailingCountry =
                    newCountryByAccountId.get(contact.AccountId);
                contactsToUpdate.add(contact);
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
