import { getRecord, getFieldValue } from 'lightning/uiRecordApi';

import ACCOUNT_NAME from '@salesforce/schema/Account.Name';
import ACCOUNT_INDUSTRY from '@salesforce/schema/Account.Industry';
import ACCOUNT_ANNUAL_REVENUE from '@salesforce/schema/Account.AnnualRevenue';
import ACCOUNT_OWNER_NAME from '@salesforce/schema/Account.Owner.Name';

const FIELDS = [
    ACCOUNT_NAME,
    ACCOUNT_INDUSTRY,
    ACCOUNT_ANNUAL_REVENUE,
    ACCOUNT_OWNER_NAME
];

export default class AccountHeader extends LightningElement {
    _recordId;
    account;
    error;

    @api
    get recordId() {
        return this._recordId;
    }

    set recordId(value) {
        if (value !== this._recordId) {
            this._recordId = value;
            this.account = undefined;
            this.error = undefined;
        }
    }

    @wire(getRecord, { recordId: '$recordId', fields: FIELDS })
    wiredAccount({ data, error }) {
        if (data) {
            this.account = data;
            this.error = undefined;
        } else if (error) {
            this.account = undefined;
            this.error = error;
        } else {
            this.account = undefined;
            this.error = undefined;
        }
    }

    get isLoading() {
        return !this.account && !this.error;
    }

    get hasError() {
        return Boolean(this.error);
    }

    get accountName() {
        return getFieldValue(this.account, ACCOUNT_NAME);
    }

    get industry() {
        return getFieldValue(this.account, ACCOUNT_INDUSTRY);
    }

    get annualRevenue() {
        return getFieldValue(this.account, ACCOUNT_ANNUAL_REVENUE);
    }

    get ownerName() {
        return getFieldValue(this.account, ACCOUNT_OWNER_NAME);
    }

    get errorMessage() {
        return this.error?.body?.message;
    }
}
