import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY = 300;
const MINIMUM_SEARCH_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    results = [];
    error;

    debounceTimeout;
    requestSequence = 0;
    componentConnected = false;

    connectedCallback() {
        this.componentConnected = true;
    }

    disconnectedCallback() {
        this.componentConnected = false;
        this.requestSequence += 1;

        if (this.debounceTimeout) {
            clearTimeout(this.debounceTimeout);
            this.debounceTimeout = undefined;
        }
    }

    handleChange(event) {
        const searchTerm = event.target.value.trim();
        const requestId = ++this.requestSequence;

        if (this.debounceTimeout) {
            clearTimeout(this.debounceTimeout);
            this.debounceTimeout = undefined;
        }

        this.error = undefined;

        if (searchTerm.length < MINIMUM_SEARCH_LENGTH) {
            this.results = [];
            return;
        }

        this.debounceTimeout = setTimeout(() => {
            this.debounceTimeout = undefined;

            if (
                !this.componentConnected ||
                requestId !== this.requestSequence
            ) {
                return;
            }

            this.performSearch(searchTerm, requestId);
        }, DEBOUNCE_DELAY);
    }

    async performSearch(searchTerm, requestId) {
        try {
            const contacts = await searchContacts({ searchTerm });

            if (
                this.componentConnected &&
                requestId === this.requestSequence
            ) {
                this.results = contacts;
                this.error = undefined;
            }
        } catch (error) {
            if (
                this.componentConnected &&
                requestId === this.requestSequence
            ) {
                this.results = [];
                this.error = error;
            }
        }
    }
}
