            this.opportunities = [];
            this.errorMessage = error.body.message;
        } finally {
            this.isLoading = false;
        }
    }

    handleRetry() {
        this.loadOpportunities();
    }

    get hasOpportunities() {
        return this.opportunities.length > 0;
