import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    hasStats = false;
    errorMessage;

    intervalId;
    requestInFlight = false;
    isConnected = false;
    lifecycleId = 0;

    constructor() {
        super();
        this.handleVisibilityChange =
            this.handleVisibilityChange.bind(this);
    }

    connectedCallback() {
        this.isConnected = true;
        this.lifecycleId += 1;
        this.hasStats = false;
        this.errorMessage = undefined;

        document.addEventListener(
            'visibilitychange',
            this.handleVisibilityChange
        );

        if (document.visibilityState === 'visible') {
            this.startPolling();
        }
    }

    disconnectedCallback() {
        this.isConnected = false;
        this.lifecycleId += 1;
        this.stopPolling();

        document.removeEventListener(
            'visibilitychange',
            this.handleVisibilityChange
        );
    }

    handleVisibilityChange() {
        if (!this.isConnected) {
            return;
        }

        if (document.visibilityState === 'visible') {
            this.startPolling();
        } else {
            this.stopPolling();
        }
    }

    startPolling() {
        this.stopPolling();
        this.refreshStats();

        this.intervalId = window.setInterval(() => {
            this.refreshStats();
        }, REFRESH_INTERVAL_MS);
    }

    stopPolling() {
        if (this.intervalId !== undefined) {
            window.clearInterval(this.intervalId);
            this.intervalId = undefined;
        }
    }

    async refreshStats() {
        if (
            !this.isConnected ||
            document.visibilityState !== 'visible' ||
            this.requestInFlight
        ) {
            return;
        }

        this.requestInFlight = true;
        const requestLifecycleId = this.lifecycleId;

        try {
            const stats = await getQueueStats();

            if (
                !this.isConnected ||
                requestLifecycleId !== this.lifecycleId
            ) {
                return;
            }

            this.waiting = stats.waiting;
            this.longestWaitMinutes = stats.longestWaitMinutes;
            this.hasStats = true;
            this.errorMessage = undefined;
        } catch (error) {
            if (
                !this.isConnected ||
                requestLifecycleId !== this.lifecycleId
            ) {
                return;
            }

            this.errorMessage =
                error?.body?.message ?? 'Unable to load queue statistics.';
        } finally {
            this.requestInFlight = false;

            if (
                this.isConnected &&
                requestLifecycleId !== this.lifecycleId &&
                document.visibilityState === 'visible'
            ) {
                this.refreshStats();
            }
        }
    }
}
