import { api, LightningElement } from 'lwc';

let nextInstanceId = 0;

const HANDLED_KEYS = new Set([
    'ArrowDown',
    'ArrowUp',
    'Home',
    'End',
    'Enter',
    ' '
]);

export default class StatusListbox extends LightningElement {
    @api label = '';

    _options = [];
    _value = '';
    _activeIndex = -1;
    _instanceId;

    constructor() {
        super();
        nextInstanceId += 1;
        this._instanceId = nextInstanceId;
    }

    @api
    get options() {
        return this._options;
    }

    set options(options) {
        this._options = Array.isArray(options) ? [...options] : [];
        this.syncActiveToValue();
    }

    @api
    get value() {
        return this._value;
    }

    set value(value) {
        this._value = value ?? '';
        this.syncActiveToValue();
    }

    get renderedOptions() {
        return this._options.map((option, index) => ({
            ...option,
            index,
            id: this.optionId(index),
            ariaSelected: option.value === this._value ? 'true' : 'false'
        }));
    }

    get activeOptionId() {
        return this._activeIndex >= 0
            ? this.optionId(this._activeIndex)
            : null;
    }

    renderedCallback() {
        // LWC can scope DOM IDs at runtime. Reference the option's actual
        // rendered ID so aria-activedescendant always resolves correctly.
        const listbox = this.template.querySelector('[role="listbox"]');
        const optionElements =
            this.template.querySelectorAll('[role="option"]');
        const activeOption = optionElements[this._activeIndex];

        if (activeOption) {
            listbox.setAttribute(
                'aria-activedescendant',
                activeOption.id
            );
        } else {
            listbox.removeAttribute('aria-activedescendant');
        }
    }

    handleKeyDown(event) {
        if (!HANDLED_KEYS.has(event.key)) {
            return;
        }

        event.preventDefault();

        if (this._options.length === 0) {
            return;
        }

        switch (event.key) {
            case 'ArrowDown':
                this._activeIndex = Math.min(
                    this._activeIndex + 1,
                    this._options.length - 1
                );
                break;
            case 'ArrowUp':
                this._activeIndex = Math.max(this._activeIndex - 1, 0);
                break;
            case 'Home':
                this._activeIndex = 0;
                break;
            case 'End':
                this._activeIndex = this._options.length - 1;
                break;
            case 'Enter':
            case ' ':
                this.selectActiveOption();
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const index = Number(event.currentTarget.dataset.index);

        if (!Number.isInteger(index) || !this._options[index]) {
            return;
        }

        this._activeIndex = index;
        this.selectActiveOption();
    }

    selectActiveOption() {
        const option = this._options[this._activeIndex];

        if (!option || option.value === this._value) {
            return;
        }

        this._value = option.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: {
                    value: option.value
                }
            })
        );
    }

    syncActiveToValue() {
        const selectedIndex = this._options.findIndex(
            (option) => option.value === this._value
        );

        this._activeIndex =
            selectedIndex >= 0
                ? selectedIndex
                : this._options.length > 0
                  ? 0
                  : -1;
    }

    optionId(index) {
        return `status-listbox-${this._instanceId}-option-${index}`;
    }
}
