import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    _heading;
    _tasks = [];
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get heading() {
        return this._heading;
    }

    set heading(value) {
        this._heading = value;
    }

    @api
    get tasks() {
        return this._tasks;
    }

    set tasks(value) {
        this._tasks = value;
        this.items = Array.isArray(value) ? value.map((task) => ({ ...task })) : [];
    }

    get displayHeading() {
        return this._heading == null ? '' : String(this._heading).toUpperCase();
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = String(this.newLabel || '').trim();

        if (!label) {
            return;
        }

        let id;
        do {
            id = `new-${this.nextId++}`;
        } while (this.items.some((task) => String(task.id) === id));

        this.items = [...this.items, { id, label, done: false }];
        this.newLabel = '';

        this.dispatchEvent(
            new CustomEvent('taskadded', {
                detail: { label }
            })
        );
    }

    handleToggle(event) {
        const id = event.currentTarget.dataset.id;
        const done = event.currentTarget.checked;

        this.items = this.items.map((task) =>
            String(task.id) === id ? { ...task, done } : task
        );
    }
}
