public with sharing class EmployerService {
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>();
        for (Id contactId : employerByContactId.keySet()) {
            if (contactId != null && employerByContactId.get(contactId) != null) {
                contactIds.add(contactId);
            }
        }

        if (contactIds.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact contactRecord : [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
            WITH USER_MODE
        ]) {
            Id organizationId = employerByContactId.get(contactRecord.Id);

            if (contactRecord.npsp__Primary_Affiliation__c != organizationId) {
                contactsToUpdate.add(new Contact(
                    Id = contactRecord.Id,
                    npsp__Primary_Affiliation__c = organizationId
                ));
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            /*
             * Updating NPSP's Primary Affiliation field invokes NPSP's standard
             * affiliation management. NPSP creates or promotes the affiliation
             * and closes the previous primary affiliation without changing the
             * contact's household AccountId.
             */
            update as user contactsToUpdate;
        }
    }
}
