        List<Id> recurringGiftIds = new List<Id>();

        if (requests == null || requests.isEmpty()) {
            return recurringGiftIds;
        }

        validateRequests(requests);

        List<npe03__Recurring_Donation__c> recurringGifts =
            new List<npe03__Recurring_Donation__c>();

        for (GiftRequest request : requests) {
            Boolean isOpenEnded =
                request.installments == null || request.installments == 0;
            Boolean useLastDayOfMonth = request.dayOfMonth == 31;
            Date firstPaymentDate = firstScheduledDate(
                request.startDate,
                request.dayOfMonth
            );

            npe03__Recurring_Donation__c recurringGift =
                new npe03__Recurring_Donation__c(
                    Name = 'Monthly Gift - ' + String.valueOf(request.startDate),
                    npe03__Contact__c = request.contactId,
                    npe03__Organization__c = null,
                    npe03__Amount__c = request.amount,
                    npe03__Installment_Period__c = 'Monthly',
                    npe03__Schedule_Type__c = 'Multiply By',
                    npe03__Open_Ended_Status__c = isOpenEnded ? 'Open' : 'None',
                    npe03__Date_Established__c = request.startDate,
                    npe03__Next_Payment_Date__c = firstPaymentDate,
                    npsp__RecurringType__c = isOpenEnded ? 'Open' : 'Fixed',
                    npsp__InstallmentFrequency__c = 1,
                    npsp__Day_of_Month__c = request.dayOfMonth,
                    npsp__Always_Use_Last_Day_Of_Month__c = useLastDayOfMonth,
                    npsp__StartDate__c = request.startDate,
                    npsp__Status__c = 'Active',
                    npsp__PaymentMethod__c = request.paymentMethod
                );

            if (!isOpenEnded) {
                recurringGift.npe03__Installments__c = request.installments;
                recurringGift.npsp__EndDate__c = scheduledDateInMonth(
                    Date.newInstance(
                        firstPaymentDate.year(),
                        firstPaymentDate.month(),
                        1
                    ).addMonths(request.installments - 1),
                    request.dayOfMonth
                );
            }

            recurringGifts.add(recurringGift);
        }

        insert as user recurringGifts;

        for (npe03__Recurring_Donation__c recurringGift : recurringGifts) {
            recurringGiftIds.add(recurringGift.Id);
        }

        return recurringGiftIds;
    }

    private static void validateRequests(List<GiftRequest> requests) {
        for (Integer index = 0; index < requests.size(); index++) {
            GiftRequest request = requests[index];

            if (request == null) {
                throw new RecurringGiftException(
                    'Gift request at index ' + index + ' must not be null.'
                );
            }
            if (request.contactId == null) {
                throw new RecurringGiftException(
                    'Contact is required for gift request at index ' + index + '.'
                );
            }
            if (request.amount == null || request.amount <= 0) {
                throw new RecurringGiftException(
                    'Amount must be positive for gift request at index ' + index + '.'
                );
            }
            if (
                request.dayOfMonth == null ||
                request.dayOfMonth < 1 ||
                request.dayOfMonth > 31
            ) {
                throw new RecurringGiftException(
                    'Day of month must be between 1 and 31 for gift request at index ' +
                    index +
                    '.'
                );
            }
            if (request.startDate == null) {
                throw new RecurringGiftException(
                    'Start date is required for gift request at index ' + index + '.'
                );
            }
            if (request.installments != null && request.installments < 0) {
                throw new RecurringGiftException(
                    'Installments cannot be negative for gift request at index ' +
                    index +
                    '.'
                );
            }
        }
    }

    private static Date firstScheduledDate(Date startDate, Integer dayOfMonth) {
        Date monthStart = Date.newInstance(
            startDate.year(),
            startDate.month(),
            1
        );
        Date scheduledDate = scheduledDateInMonth(monthStart, dayOfMonth);

        if (scheduledDate < startDate) {
            scheduledDate = scheduledDateInMonth(
                monthStart.addMonths(1),
                dayOfMonth
            );
        }

        return scheduledDate;
    }

    private static Date scheduledDateInMonth(
        Date monthStart,
        Integer dayOfMonth
    ) {
        Date lastDateOfMonth = monthStart.addMonths(1).addDays(-1);
        Integer scheduledDay = dayOfMonth > lastDateOfMonth.day()
            ? lastDateOfMonth.day()
            : dayOfMonth;

        return Date.newInstance(
            monthStart.year(),
            monthStart.month(),
            scheduledDay
        );
    }
