public with sharing class GauAllocationService {
    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId
    ) {
        if (opportunityId == null) {
            throw new AllocationException('An Opportunity Id is required.');
        }

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU allocation is required.');
        }

        Decimal totalPercent = 0;
        Set<Id> gauIds = new Set<Id>();

        for (Id gauId : percentByGauId.keySet()) {
            if (
                gauId == null ||
                gauId.getSObjectType() != npsp__General_Accounting_Unit__c.SObjectType
            ) {
                throw new AllocationException('Every allocation must reference a valid GAU Id.');
            }

            Decimal allocationPercent = percentByGauId.get(gauId);
            if (allocationPercent == null || allocationPercent <= 0) {
                throw new AllocationException(
                    'Every allocation percentage must be greater than zero.'
                );
            }

            gauIds.add(gauId);
            totalPercent += allocationPercent;
        }

        if (totalPercent > 100) {
            throw new AllocationException(
                'The combined allocation percentage cannot exceed 100%.'
            );
        }

        List<Opportunity> opportunities = [
            SELECT Id
            FROM Opportunity
            WHERE Id = :opportunityId
            WITH USER_MODE
            FOR UPDATE
        ];

        if (opportunities.isEmpty()) {
            throw new AllocationException('The specified Opportunity does not exist.');
        }

        Map<Id, npsp__General_Accounting_Unit__c> gausById =
            new Map<Id, npsp__General_Accounting_Unit__c>([
                SELECT Id, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :gauIds
                WITH USER_MODE
            ]);

        if (gausById.size() != gauIds.size()) {
            throw new AllocationException('One or more specified GAUs do not exist.');
        }

        for (Id gauId : gauIds) {
            if (gausById.get(gauId).npsp__Active__c != true) {
                throw new AllocationException('All specified GAUs must be active.');
            }
        }

        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
            WITH USER_MODE
        ];

        List<npsp__Allocation__c> newAllocations =
            new List<npsp__Allocation__c>();

        for (Id gauId : percentByGauId.keySet()) {
            newAllocations.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
            ));
        }

        Savepoint replacementSavepoint = Database.setSavepoint();

        try {
            if (!existingAllocations.isEmpty()) {
                Database.delete(existingAllocations, AccessLevel.USER_MODE);
            }

            Database.insert(newAllocations, AccessLevel.USER_MODE);
            return newAllocations;
        } catch (Exception exceptionToRethrow) {
            Database.rollback(replacementSavepoint);
            throw exceptionToRethrow;
        }
    }
