public inherited sharing class HouseholdService {
    private static final String HOUSEHOLD_RECORD_TYPE_DEVELOPER_NAME = 'HH_Account';

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('At least one household member is required.');
        }

        for (Contact member : members) {
            if (member == null) {
                throw new IllegalArgumentException('Household members cannot contain null entries.');
            }
            if (member.Id != null || member.AccountId != null) {
                throw new IllegalArgumentException(
                    'Household members must be new contacts without an AccountId.'
                );
            }
        }

        Schema.RecordTypeInfo householdRecordType =
            Schema.SObjectType.Account
                .getRecordTypeInfosByDeveloperName()
                .get(HOUSEHOLD_RECORD_TYPE_DEVELOPER_NAME);

        if (householdRecordType == null) {
            throw new HouseholdCreationException(
                'The NPSP Household Account record type was not found.'
            );
        }

        Savepoint savepoint = Database.setSavepoint();

        try {
            /*
             * Inserting the first contact without an AccountId lets NPSP create
             * and name exactly one household using its configured automation.
             */
            insert members[0];

            Contact persistedPrimaryContact = [
                SELECT Id, AccountId
                FROM Contact
                WHERE Id = :members[0].Id
                LIMIT 1
            ];

            if (persistedPrimaryContact.AccountId == null) {
                throw new HouseholdCreationException(
                    'NPSP did not create a household for the primary contact.'
                );
            }

            Id householdId = persistedPrimaryContact.AccountId;
            members[0].AccountId = householdId;

            Account household = [
                SELECT Id, RecordTypeId, npe01__One2OneContact__c
                FROM Account
                WHERE Id = :householdId
                LIMIT 1
            ];

            if (household.RecordTypeId != householdRecordType.getRecordTypeId()) {
                throw new HouseholdCreationException(
                    'NPSP created an account that is not a Household Account.'
                );
            }

            if (members.size() > 1) {
                List<Contact> additionalMembers = new List<Contact>();

                for (Integer index = 1; index < members.size(); index++) {
                    members[index].AccountId = householdId;
                    additionalMembers.add(members[index]);
                }

                insert additionalMembers;
            }

            if (household.npe01__One2OneContact__c != persistedPrimaryContact.Id) {
                household.npe01__One2OneContact__c = persistedPrimaryContact.Id;
                update household;
            }

            return householdId;
        } catch (Exception exceptionToRethrow) {
            Database.rollback(savepoint);
            throw exceptionToRethrow;
        }
    }

    public class HouseholdCreationException extends Exception {
    }
}
