public inherited sharing class PaymentPlanService {
    public class PaymentPlanException extends Exception {}

    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException(
                'The number of payments must be at least one.'
            );
        }

        if (firstPaymentDate == null) {
            throw new PaymentPlanException(
                'The first payment date is required.'
            );
        }

        Opportunity donation = [
            SELECT Id, Amount, IsClosed
            FROM Opportunity
            WHERE Id = :opportunityId
            WITH USER_MODE
            LIMIT 1
            FOR UPDATE
        ];

        if (donation.IsClosed) {
            throw new PaymentPlanException(
                'A payment plan cannot be created for a closed opportunity.'
            );
        }

        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id,
                   npe01__Payment_Amount__c,
                   npe01__Paid__c,
                   npe01__Written_Off__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            WITH USER_MODE
            FOR UPDATE
        ];

        Decimal historicalAmount = 0;
        List<npe01__OppPayment__c> paymentsToDelete =
            new List<npe01__OppPayment__c>();

        for (npe01__OppPayment__c payment : existingPayments) {
            Boolean isHistorical =
                payment.npe01__Paid__c == true ||
                payment.npe01__Written_Off__c == true;

            if (isHistorical) {
                historicalAmount += payment.npe01__Payment_Amount__c == null
                    ? 0
                    : payment.npe01__Payment_Amount__c;
            } else {
                paymentsToDelete.add(payment);
            }
        }

        Decimal opportunityAmount = donation.Amount == null
            ? 0
            : donation.Amount;
        Decimal outstandingAmount = opportunityAmount - historicalAmount;

        if (outstandingAmount <= 0) {
            throw new PaymentPlanException(
                'The opportunity must have an outstanding amount greater than zero.'
            );
        }

        Decimal regularPaymentAmount =
            (outstandingAmount / numberOfPayments)
                .setScale(2, RoundingMode.DOWN);

        List<npe01__OppPayment__c> installments =
            new List<npe01__OppPayment__c>();

        for (Integer i = 0; i < numberOfPayments; i++) {
            Decimal paymentAmount = i == numberOfPayments - 1
                ? outstandingAmount -
                    (regularPaymentAmount * (numberOfPayments - 1))
                : regularPaymentAmount;

            installments.add(new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = paymentAmount,
                npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i),
                npe01__Payment_Date__c = null,
                npe01__Paid__c = false,
                npe01__Written_Off__c = false
            ));
        }

        Savepoint savepoint = Database.setSavepoint();

        try {
            if (!paymentsToDelete.isEmpty()) {
                Database.delete(paymentsToDelete, AccessLevel.USER_MODE);
            }

            Database.insert(installments, AccessLevel.USER_MODE);
        } catch (Exception exceptionThrown) {
            Database.rollback(savepoint);
            throw exceptionThrown;
        }

        return installments;
    }
}
