public inherited sharing class FamilyService {
    /**
     * Creates NPSP Parent relationships for the supplied child-to-parent pairs.
     *
     * NPSP's relationship automation creates and links the reciprocal
     * Son, Daughter, or Child record according to the configured Parent
     * Relationship Lookup.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Map<String, ContactPair> requestedPairsByKey = new Map<String, ContactPair>();
        Set<Id> childIds = new Set<Id>();
        Set<Id> parentIds = new Set<Id>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            // Ignore incomplete and self-referential relationships.
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }

            String pairKey = canonicalPairKey(childId, parentId);

            // Also prevents duplicate work if the same unordered pair appears
            // in both directions in the input.
            if (!requestedPairsByKey.containsKey(pairKey)) {
                requestedPairsByKey.put(
                    pairKey,
                    new ContactPair(childId, parentId)
                );
                childIds.add(childId);
                parentIds.add(parentId);
            }
        }

        if (requestedPairsByKey.isEmpty()) {
            return;
        }

        Set<String> existingPairKeys = new Set<String>();

        /*
         * This system-mode read is intentionally limited to duplicate
         * detection. It prevents creation of duplicate relationships even
         * when an existing relationship is not shared with the caller.
         */
        for (npe4__Relationship__c relationship : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE (
                npe4__Contact__c IN :childIds
                AND npe4__RelatedContact__c IN :parentIds
            )
            OR (
                npe4__Contact__c IN :parentIds
                AND npe4__RelatedContact__c IN :childIds
            )
        ]) {
            if (
                relationship.npe4__Contact__c == null ||
                relationship.npe4__RelatedContact__c == null
            ) {
                continue;
            }

            String pairKey = canonicalPairKey(
                relationship.npe4__Contact__c,
                relationship.npe4__RelatedContact__c
            );

            if (requestedPairsByKey.containsKey(pairKey)) {
                existingPairKeys.add(pairKey);
            }
        }

        List<npe4__Relationship__c> relationshipsToInsert =
            new List<npe4__Relationship__c>();

        for (String pairKey : requestedPairsByKey.keySet()) {
            if (existingPairKeys.contains(pairKey)) {
                continue;
            }

            ContactPair pair = requestedPairsByKey.get(pairKey);
            relationshipsToInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = pair.childId,
                npe4__RelatedContact__c = pair.parentId,
                npe4__Type__c = 'Parent',
                npe4__Status__c = 'Current'
            ));
        }

        if (!relationshipsToInsert.isEmpty()) {
            // NPSP creates and links the reciprocal relationship in its trigger.
            insert as user relationshipsToInsert;
        }
    }

    private static String canonicalPairKey(Id firstId, Id secondId) {
        String first = String.valueOf(firstId);
        String second = String.valueOf(secondId);

        return first.compareTo(second) <= 0
            ? first + ':' + second
            : second + ':' + first;
    }

    private class ContactPair {
        private Id childId;
        private Id parentId;

        private ContactPair(Id childId, Id parentId) {
            this.childId = childId;
            this.parentId = parentId;
        }
    }
}
