global inherited sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {
    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;
    private static final String CLOSED_WON_STAGE = 'Closed Won';

    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper =
            new npsp.TDTM_Runnable.DmlWrapper();

        Boolean isAfterInsert =
            triggerAction == npsp.TDTM_Runnable.Action.AfterInsert;
        Boolean isAfterUpdate =
            triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate;

        if (!isAfterInsert && !isAfterUpdate) {
            return dmlWrapper;
        }

        List<Task> tasksToInsert = new List<Task>();

        for (Integer i = 0; i < newlist.size(); i++) {
            Opportunity newOpportunity = (Opportunity) newlist[i];

            if (!qualifiesAsMajorGift(newOpportunity)) {
                continue;
            }

            Boolean previouslyQualified = false;
            if (isAfterUpdate && oldlist != null && i < oldlist.size()) {
                previouslyQualified =
                    qualifiesAsMajorGift((Opportunity) oldlist[i]);
            }

            if (previouslyQualified) {
                continue;
            }

            tasksToInsert.add(new Task(
                Subject = 'Major gift thank-you call',
                Priority = 'High',
                Status = 'Not Started',
                WhatId = newOpportunity.Id,
                WhoId = newOpportunity.npsp__Primary_Contact__c,
                OwnerId = newOpportunity.OwnerId,
                ActivityDate = newOpportunity.CloseDate == null
                    ? null
                    : newOpportunity.CloseDate.addDays(3)
            ));
        }

        dmlWrapper.objectsToInsert.addAll(tasksToInsert);
        return dmlWrapper;
    }

    private static Boolean qualifiesAsMajorGift(Opportunity opportunity) {
        return opportunity.StageName == CLOSED_WON_STAGE
            && opportunity.Amount != null
            && opportunity.Amount >= MAJOR_GIFT_THRESHOLD;
    }
}
