public with sharing class EmployeeDirectoryService {
    public static List<FB_Employee__c> getDirectory() {
        if (!Schema.sObjectType.FB_Employee__c.getDescribe().isAccessible()) {
            return new List<FB_Employee__c>();
        }

        List<String> selectedFields = new List<String>{ 'Id', 'Name' };

        Map<String, Schema.SObjectField> fieldMap =
            Schema.sObjectType.FB_Employee__c.fields.getMap();

        for (String fieldName : new List<String>{
            'Department__c',
            'Salary__c',
            'Personal_Email__c'
        }) {
            if (fieldMap.get(fieldName).getDescribe().isAccessible()) {
                selectedFields.add(fieldName);
            }
        }

        String query =
            'SELECT ' + String.join(selectedFields, ', ') +
            ' FROM FB_Employee__c' +
            ' ORDER BY Name ASC';

        return Database.query(query, AccessLevel.USER_MODE);
    }
}
