@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {
    @IsTest
    static void rejectsReductionOfMoreThanHalf() {
        Id opportunityId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        Opportunity oldOpportunity = new Opportunity(
            Id = opportunityId,
            Amount = 1000
        );
        Opportunity newOpportunity = new Opportunity(
            Id = opportunityId,
            Amount = 499
        );

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpportunity },
            new List<Opportunity>{ oldOpportunity }
        );

        System.assertEquals(true, newOpportunity.hasErrors());
        System.assertEquals(1, newOpportunity.getErrors().size());
        System.assertEquals(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            newOpportunity.getErrors()[0].getMessage()
        );
    }

    @IsTest
    static void acceptsReductionOfExactlyHalf() {
        Id opportunityId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        Opportunity oldOpportunity = new Opportunity(
            Id = opportunityId,
            Amount = 1000
        );
        Opportunity newOpportunity = new Opportunity(
            Id = opportunityId,
            Amount = 500
        );

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpportunity },
            new List<Opportunity>{ oldOpportunity }
        );

        System.assertEquals(false, newOpportunity.hasErrors());
        System.assertEquals(0, newOpportunity.getErrors().size());
    }

    @IsTest
    static void acceptsIncreaseAndNullPreviousAmount() {
        Id increasedOpportunityId =
            TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id nullPreviousAmountOpportunityId =
            TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        Opportunity increasedOldOpportunity = new Opportunity(
            Id = increasedOpportunityId,
            Amount = 1000
        );
        Opportunity increasedNewOpportunity = new Opportunity(
            Id = increasedOpportunityId,
            Amount = 1500
        );

        Opportunity nullAmountOldOpportunity = new Opportunity(
            Id = nullPreviousAmountOpportunityId,
            Amount = null
        );
        Opportunity nullAmountNewOpportunity = new Opportunity(
            Id = nullPreviousAmountOpportunityId,
            Amount = 100
        );

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{
                increasedNewOpportunity,
                nullAmountNewOpportunity
            },
            new List<Opportunity>{
                increasedOldOpportunity,
                nullAmountOldOpportunity
            }
        );

        System.assertEquals(false, increasedNewOpportunity.hasErrors());
        System.assertEquals(0, increasedNewOpportunity.getErrors().size());
        System.assertEquals(false, nullAmountNewOpportunity.hasErrors());
        System.assertEquals(0, nullAmountNewOpportunity.getErrors().size());
    }

    @IsTest
    static void addsErrorsOnlyToInvalidRecordsInBulk() {
        Id firstRejectedId =
            TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id exactHalfId =
            TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id increasedId =
            TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id nullPreviousAmountId =
            TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id secondRejectedId =
            TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        List<Opportunity> triggerOld = new List<Opportunity>{
            new Opportunity(Id = firstRejectedId, Amount = 1000),
            new Opportunity(Id = exactHalfId, Amount = 1000),
            new Opportunity(Id = increasedId, Amount = 100),
            new Opportunity(Id = nullPreviousAmountId, Amount = null),
            new Opportunity(Id = secondRejectedId, Amount = 200)
        };
        List<Opportunity> triggerNew = new List<Opportunity>{
            new Opportunity(Id = firstRejectedId, Amount = 499),
            new Opportunity(Id = exactHalfId, Amount = 500),
            new Opportunity(Id = increasedId, Amount = 101),
            new Opportunity(Id = nullPreviousAmountId, Amount = 1),
            new Opportunity(Id = secondRejectedId, Amount = 99)
        };

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            triggerNew,
            triggerOld
        );

        Integer recordsWithErrors = 0;
        for (Opportunity opportunity : triggerNew) {
            if (opportunity.hasErrors()) {
                recordsWithErrors++;
            }
        }

        System.assertEquals(2, recordsWithErrors);

        System.assertEquals(true, triggerNew[0].hasErrors());
        System.assertEquals(1, triggerNew[0].getErrors().size());
        System.assertEquals(
