            triggerNew[0].getErrors()[0].getMessage()
        );

        System.assertEquals(false, triggerNew[1].hasErrors());
        System.assertEquals(0, triggerNew[1].getErrors().size());

        System.assertEquals(false, triggerNew[2].hasErrors());
        System.assertEquals(0, triggerNew[2].getErrors().size());

        System.assertEquals(false, triggerNew[3].hasErrors());
        System.assertEquals(0, triggerNew[3].getErrors().size());

        System.assertEquals(true, triggerNew[4].hasErrors());
        System.assertEquals(1, triggerNew[4].getErrors().size());
        System.assertEquals(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            triggerNew[4].getErrors()[0].getMessage()
        );
    }
