public without sharing class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        preventDuplicates(triggerNew, null, false);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        preventDuplicates(triggerNew, triggerOld, true);
    }

    private static void preventDuplicates(
        List<SObject> triggerNew,
        List<SObject> triggerOld,
        Boolean isUpdate
    ) {
        List<Contact> contactsToCheck = new List<Contact>();
        Set<Id> changingContactIds = new Set<Id>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Contact newContact = (Contact) triggerNew[i];

            if (newContact.AccountId == null || String.isBlank(newContact.Email)) {
                continue;
            }

            if (isUpdate) {
                Contact oldContact = (Contact) triggerOld[i];
                Boolean accountChanged = newContact.AccountId != oldContact.AccountId;
                Boolean emailChanged = stringsDiffer(newContact.Email, oldContact.Email);

                if (!accountChanged && !emailChanged) {
                    continue;
                }

                changingContactIds.add(newContact.Id);
            }

            contactsToCheck.add(newContact);
            accountIds.add(newContact.AccountId);
            emails.add(newContact.Email);
        }

        if (contactsToCheck.isEmpty()) {
            return;
        }

        Set<String> occupiedKeys = new Set<String>();

        for (Contact existingContact : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Email IN :emails
        ]) {
            // Updated records being evaluated are represented by their proposed
            // values below, rather than by their currently persisted values.
            if (!changingContactIds.contains(existingContact.Id)) {
                occupiedKeys.add(buildKey(
                    existingContact.AccountId,
                    existingContact.Email
                ));
            }
        }

        // Preserve trigger-list order so the first proposed occurrence is accepted.
        for (Contact contactToCheck : contactsToCheck) {
            String key = buildKey(
                contactToCheck.AccountId,
                contactToCheck.Email
            );

            if (occupiedKeys.contains(key)) {
                contactToCheck.addError(ERROR_MESSAGE);
            } else {
                occupiedKeys.add(key);
            }
        }
    }

    private static Boolean stringsDiffer(String firstValue, String secondValue) {
        if (firstValue == null || secondValue == null) {
            return firstValue != secondValue;
        }

        return !firstValue.equals(secondValue);
    }

    private static String buildKey(Id accountId, String email) {
        return String.valueOf(accountId) + '|' + email.toLowerCase();
    }
}
