public without sharing class TA_Case_RollupOpenCount implements
    TriggerAction.AfterInsert,
    TriggerAction.AfterUpdate,
    TriggerAction.AfterDelete,
    TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();

        for (SObject record : triggerNew) {
            Case caseRecord = (Case) record;
            if (caseRecord.AccountId != null) {
                accountIds.add(caseRecord.AccountId);
            }
        }

        rollupOpenCaseCounts(accountIds);
    }

    public void afterUpdate(
        List<SObject> triggerNew,
        List<SObject> triggerOld
    ) {
        Set<Id> accountIds = new Set<Id>();

        for (Integer index = 0; index < triggerNew.size(); index++) {
            Case newCase = (Case) triggerNew[index];
            Case oldCase = (Case) triggerOld[index];

            Boolean accountChanged = newCase.AccountId != oldCase.AccountId;
            Boolean closedStateChanged = newCase.IsClosed != oldCase.IsClosed;

            if (!accountChanged && !closedStateChanged) {
                continue;
            }

            if (oldCase.AccountId != null) {
                accountIds.add(oldCase.AccountId);
            }
            if (newCase.AccountId != null) {
                accountIds.add(newCase.AccountId);
            }
        }

        rollupOpenCaseCounts(accountIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();

        for (SObject record : triggerOld) {
            Case caseRecord = (Case) record;
            if (caseRecord.AccountId != null) {
                accountIds.add(caseRecord.AccountId);
            }
        }

        rollupOpenCaseCounts(accountIds);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();

        for (SObject record : triggerNew) {
            Case caseRecord = (Case) record;
            if (caseRecord.AccountId != null) {
                accountIds.add(caseRecord.AccountId);
            }
        }

        rollupOpenCaseCounts(accountIds);
    }

    private static void rollupOpenCaseCounts(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        List<Account> accountsToUpdate = [
            SELECT Id, FB_Open_Case_Count__c
            FROM Account
            WHERE Id IN :accountIds
            FOR UPDATE
        ];

        if (accountsToUpdate.isEmpty()) {
            return;
        }

        Set<Id> lockedAccountIds = new Map<Id, Account>(
            accountsToUpdate
        ).keySet();

        Map<Id, Integer> openCaseCountsByAccountId = new Map<Id, Integer>();

        for (AggregateResult result : [
            SELECT AccountId accountId, COUNT(Id) openCaseCount
            FROM Case
            WHERE AccountId IN :lockedAccountIds
                AND IsClosed = FALSE
            GROUP BY AccountId
        ]) {
            openCaseCountsByAccountId.put(
                (Id) result.get('accountId'),
                (Integer) result.get('openCaseCount')
            );
        }

        for (Account accountRecord : accountsToUpdate) {
            accountRecord.FB_Open_Case_Count__c =
                openCaseCountsByAccountId.containsKey(accountRecord.Id)
                    ? openCaseCountsByAccountId.get(accountRecord.Id)
                    : 0;
        }

        update accountsToUpdate;
    }
}
